_SCALE_Y = 0.75
_SHIFT = 0.125

_FLOAT_DTYPES = (torch.float16, torch.bfloat16, torch.float32, torch.float64)
_CAPTURE_BUDGET = 4

_constants = {}     # (device, dtype) -> (bias, scale_x) 0-dim tensors
_graphs = {}        # buffer key -> (CUDAGraph, out, x, y)
_last_seen = {}     # signature -> buffer key seen on the previous call
