_SCALE_Y = 0.75
_BIAS = -0.125

# Cached 0-dim device constants, keyed by (device, dtype), so the fused
# expression below costs no host->device transfer per call.
_SCALAR_PAIR_CACHE = {}


def _scalar_pair(x):
    key = (x.device, x.dtype)
    pair = _SCALAR_PAIR_CACHE.get(key)
    if pair is None:
